import{c as t,Q as a,j as o,m as i}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"The Claude Fable 5 Review: One Billion Tokens, Judged by a Non-Engineer","description":"","frontmatter":{"url":"https://x.com/JJEnglert/status/2064420538798260388","title":"The Claude Fable 5 Review: One Billion Tokens, Judged by a Non-Engineer","author":"JJ Englert","archived":"2026-06-13T00:00:00.000Z","handle":"@JJEnglert","published":"2026-06-09T00:00:00.000Z","stats":"556 likes · 36 retweets · 852 bookmarks · 137386 views","tags":["claude-fable-5","model-review","non-engineer","cost-analysis","agentic-workflow","ui-ux"],"type":"note-tweet"},"headers":[],"relativePath":"research/tweets/2026-06-09-@JJEnglert-260388.md","filePath":"research/tweets/2026-06-09-@JJEnglert-260388.md","lastUpdated":1785909234000}'),n={name:"research/tweets/2026-06-09-@JJEnglert-260388.md"};function r(s,e,h,l,d,u){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="the-claude-fable-5-review-one-billion-tokens-judged-by-a-non-engineer-—-jjenglert" tabindex="-1">The Claude Fable 5 Review: One Billion Tokens, Judged by a Non-Engineer — @JJEnglert <a class="header-anchor" href="#the-claude-fable-5-review-one-billion-tokens-judged-by-a-non-engineer-—-jjenglert" aria-label="Permalink to &quot;The Claude Fable 5 Review: One Billion Tokens, Judged by a Non-Engineer — @JJEnglert&quot;">​</a></h1><p><strong>來源</strong>：<a href="https://x.com/JJEnglert/status/2064420538798260388" target="_blank" rel="noreferrer">https://x.com/JJEnglert/status/2064420538798260388</a><strong>作者</strong>：JJ Englert（@JJEnglert） <strong>發布日期</strong>：2026-06-09 <strong>收錄日期</strong>：2026-06-13 <strong>類型</strong>：Note Tweet（長文推文） <strong>統計</strong>：556 likes · 36 retweets · 852 bookmarks · 137386 views</p><blockquote><p>Quote @claudeai: Introducing Claude Fable 5: a Mythos-class model that we&#39;ve made safe for general use. Its capabilities exceed those of any model we&#39;ve ever made generally available.</p></blockquote><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>The Claude Fable 5 Review: One Billion Tokens, Judged by a Non-Engineer</p><p>I spent a billion tokens testing Claude Fable 5 on real projects: UI and UX, writing, strategy, security, engineering, and knowledge work. The kind of work I actually needed to ship. And I will be straight with you. It truthfully felt like I had an unfair advantage. Here is why:</p><p>First, the lens. I am not an engineer. Most model reviews come from engineers running engineering benchmarks. This one comes from a non-engineer who used Claude Fable 5 to do work that used to require a team of them. If you do knowledge work and you want to know whether this model changes your day, this is written for you.</p><p>A note on naming: Claude Fable 5 is the first model in Anthropic&#39;s new Claude 5 family, a new tier that sits above Claude Opus and the most advanced Claude model generally available. I had access to it before launch, so everything here comes from real work, not a demo.</p><h3 id="why-the-eye-test" tabindex="-1">Why the eye test <a class="header-anchor" href="#why-the-eye-test" aria-label="Permalink to &quot;Why the eye test&quot;">​</a></h3><p>Most reviews drown you in benchmarks. Scores on tests you will never run, against tasks that look nothing like your actual work. They tell you a model is smart. They do not tell you whether it earns its keep.</p><p>To be clear, the benchmarks are not in question this time. Claude Fable 5 is state of the art on essentially everything it was tested on, and by a real margin. This is a genuinely exciting release. But that is not the reason I am writing. Qualitatively, this is a step change that earns its major version bump, the same order of leap I felt when 4.5 landed last November, and that is exactly what no benchmark can show you.</p><p>I evaluate differently. I put a model into real work and watch what happens. Does it save me hours or cost me them? Does it catch what I missed? Does it feel like a partner or a tool I have to babysit? That is the eye test, and it is the standard I am holding Claude Fable 5 to here.</p><p>The short version: this is the first model in a long time that passed on every dimension that matters. Not by a little.</p><h3 id="the-lens-what-i-actually-measure" tabindex="-1">The lens: what I actually measure <a class="header-anchor" href="#the-lens-what-i-actually-measure" aria-label="Permalink to &quot;The lens: what I actually measure&quot;">​</a></h3><p>I threw all of that work at it. Here is what I look for when I judge the results:</p><ol><li>Big model feel: Does it feel like a real step up, or a slightly better version of last month?</li><li>Building and shipping: Can it take an idea to a working, shippable result?</li><li>Writing and voice: Can it sound like a person, and like me specifically?</li><li>Finding what others miss: Does it catch the hard, hidden problems?</li><li>The human factor: Does it anticipate what I need before I ask?</li></ol><p>Then I weigh all of that against cost, with real numbers. Here is how Claude Fable 5 scored.</p><h3 id="_1-big-model-feel" tabindex="-1">1. Big model feel <a class="header-anchor" href="#_1-big-model-feel" aria-label="Permalink to &quot;1. Big model feel&quot;">​</a></h3><p>I have not felt this since Opus 4.5. From the first serious task, Claude Fable 5 gave me that big model feel. The sense that you have an unfair advantage just by using it. It is a major step up, not an incremental one. Reasoning, writing, building, security. It is strong across the board, and it shows up the moment you start working.</p><p>You can also feel it thinking longer and working a problem more deliberately than other models do. The clearest sign: even when I handed it solid prep materials, it did not just stay inside them. It read my files, read the actual situation, and then went and found a better path outside the box I had drawn, instead of grinding away inside the environment I told it to work in. That initiative led to a noticeably better result than I would have gotten if it had just followed my setup.</p><h3 id="_2-building-and-shipping-ui-ux" tabindex="-1">2. Building and shipping (UI/UX) <a class="header-anchor" href="#_2-building-and-shipping-ui-ux" aria-label="Permalink to &quot;2. Building and shipping (UI/UX)&quot;">​</a></h3><p>This is where it announced itself.</p><p>I was rebuilding our Tenex site to modernize the stack for agents. Not a cosmetic rebrand. The goal was to move off the old setup onto a foundation built for the agentic era, with the tech stack, agent stack, and AEO it takes to win where the work is heading. The site is very custom, which made it hard. Here is the ladder I climbed before Claude Fable 5.</p><p>GPT 5.5 and Claude 4.8 tried the build on their own. Neither came close. So I brought the design into Figma, then pulled Figma into Claude Design. Claude Design got the closest yet, around 90 percent of the look, better than the models working alone, but it missed a lot of the motion and the special design touches. Good enough for a v1 pass, so I handed that file to 4.8 and GPT 5.5 to turn into the real site. Even then they struggled to match the Claude Design file. I had to push hard, and they landed around 85 to 90 percent, with the original Figma files to reference the whole time. At that point I was not sure I could rebuild this thing at all.</p><p>Then Claude Fable 5. It looked at all the files and said it could do better. It went straight to the source, the original Webflow site, downloaded every asset, and rebuilt the whole experience one page at a time. It nearly one-shot the entire thing.</p><p>I did not stop there though. I then built a second, entirely new site, with a fresh design: modern tech stack, agent stack, skills, SEO and AEO optimized, 80 pages ready to ship over a weekend and it turned out incredible. I would have easily charged $50k for this in the past as an agency owner. Fable legit built it in a weekend.</p><p>I also had Fable build a full programmatic clip factory, and it wired the whole stack together: @HeyGen for avatars, @HyperFrames_ for motion graphics and editing, @ElevenLabs for audio, Cloudflare Workers, and a VPS. It is not perfect yet, but it got me much further than I expected. It runs the entire pipeline: finds the topics, writes the scripts, makes the thumbnail, edits the video, composes the music, adds the motion graphics, and posts to social. I ran it in the background while I pushed through my other builds. It worked for long stretches on its own, and at one point it built itself a fetching system with webhooks to monitor renders across the different platforms. It even took clear visual direction from reference material and matched it. This is the long-horizon, run-on-its-own work that earlier models could not hold together.</p><h3 id="_3-writing-and-voice" tabindex="-1">3. Writing and voice <a class="header-anchor" href="#_3-writing-and-voice" aria-label="Permalink to &quot;3. Writing and voice&quot;">​</a></h3><p>I had been rebuilding our brand voice with a combination of GPT 5.5 and Claude 4.8: the voice style guide, the tone we write in, all of it, using our website as the reference. Both 5.5 and 4.8 did a commendable job turning the site into a voice doc.</p><p>Claude Fable 5 replicated that voice doc almost identically, then did the thing the others could not. It took the style guide and wrote with it across 80 pages of the new site: features, case studies, blog articles, playbooks. Once it was trained properly on what I wanted, it gave the most honest nod I have seen to the original reference material, and then expanded that voice cleanly across brand-new surfaces without losing it.</p><p>Two things stood out. First, it wrote like a person, not the flat AI default that everyone can now spot from a mile away. Second, it held the voice across a whole site instead of drifting after a few paragraphs, which is usually where models fall apart.</p><p>The test I use for AI writing is simple: how much do I have to redo. Most models save you the blank page and then quietly cost the time back in edits. Claude Fable 5 was the rare case where the draft was close enough to actually use.</p><h3 id="_4-finding-what-others-miss-security" tabindex="-1">4. Finding what others miss (security) <a class="header-anchor" href="#_4-finding-what-others-miss-security" aria-label="Permalink to &quot;4. Finding what others miss (security)&quot;">​</a></h3><p>This one I expected but not at this level.</p><p>I had a very large repo. Both Claude 4.8 and GPT 5.5 have been working in it without ever flagging this risk. Claude Fable 5 found a serious bug on its first go with the repo. Sneaky, well hidden, the kind two frontier models had just told me was not there. Then Fable patched it on the spot.</p><p>Sit with what that means. The bug was going to ship. Two of the best models available had signed off on the code. If I had stopped there, like most people would, it goes to production and I find out the hard way. Claude Fable 5 did not just match the other two, it caught what they missed, on the exact kind of work I am least equipped to check myself as a non-engineer. That is the value that is hard to price until the day it saves you. One catch like it can pay for the whole tool.</p><h3 id="_5-the-human-factor" tabindex="-1">5. The human factor <a class="header-anchor" href="#_5-the-human-factor" aria-label="Permalink to &quot;5. The human factor&quot;">​</a></h3><p>The thing that stuck with me most was small. I asked it a question while I was waiting on a cron job to finish. It answered, then added on its own that I had about 10 minutes left on the timer and that it would let me know when it was done. I never asked about the timer. It just knew I would want to know and gave it to me.</p><p>That is not AGI, but it is the closest thing I have felt to a model that anticipates you instead of just responding to you. That is what makes it feel less like software and more like working alongside someone sharp.</p><h3 id="the-receipts" tabindex="-1">The receipts <a class="header-anchor" href="#the-receipts" aria-label="Permalink to &quot;The receipts&quot;">​</a></h3><p>I tracked this, so here are the real numbers. Start with cost, which depends entirely on which models do the work.</p><p>Cost for this workload: Claude Fable 5 | $1,442 (1.04 Billion tokens)</p><p>But that badly undersells what I actually got. Over a few days I built a shit load of things, including a new website, all of its infrastructure, and a working agent package. As an agency, I would have charged a client $30,000 to $50,000 for that alone, easily.</p><p>So here is the question that cuts through the math: if I had to pay $1,450 in tokens the the result I achieved? 100 percent. Without hesitating. The quality was that good.</p><p>That is the lens that matters. On hours alone, even at full price, it already pays for itself several times over. Measured against what the finished work is actually worth, it is not close. The cache-heavy volume still drives the bill, which is why how you run it matters. But do not let the math fool you into thinking this is marginal. It is the best money I have spent on tooling.</p><h3 id="where-it-frustrates" tabindex="-1">Where it frustrates <a class="header-anchor" href="#where-it-frustrates" aria-label="Permalink to &quot;Where it frustrates&quot;">​</a></h3><p>You feel the meter more than any other model, and the meter is real.</p><p>The receipts above are why cost is still worth watching, even though the work was worth every dollar. Anthropic does not hide this. They call Fable 5 token-intensive by design, built to think longer and verify more, and it runs through usage limits about twice as fast as Opus or Sonnet.</p><p>That is the case for the one thing I want most: an auto-router for task complexity. Right now I have to shift gears by hand mid-conversation to conserve tokens, and I do not want to think about that. If I ask for something simple, the model should downshift on its own and handle it, saving the expensive intelligence for the work that actually needs it. This is not just about flow. It is the economics. A smart router keeps the simple work on cheap models and only escalates to Claude Fable 5 when the task earns it, which is the whole difference between 2.5 efficiency and 9.7. Until that exists, using a frontier model well means doing the routing in your own head with active shifting in model effort levels.</p><h3 id="pro-tip-1-run-it-as-a-hybrid" tabindex="-1">Pro tip #1: run it as a hybrid <a class="header-anchor" href="#pro-tip-1-run-it-as-a-hybrid" aria-label="Permalink to &quot;Pro tip #1: run it as a hybrid&quot;">​</a></h3><p>Here is how I keep the cost in check without giving up the intelligence. Do not run everything on Claude Fable 5. Run a relay across models.</p><ol><li>Think with Claude Fable 5: Use it for the expensive thinking: high-level planning, strategy, architecture, mapping the whole approach before a line of work gets done. This is where its edge is biggest and the token count is smallest.</li><li>Build with 4.8, GPT5.5 or Sonnet 4.6: Hand the plan to a cheaper model for the legwork: the implementation, the repetitive passes, the high-volume grunt work. That is the work that runs up the bill, and it does not need a frontier brain.</li><li>Review with Claude Fable 5: Bring it back to Claude Fable 5 to check the result. This is where it earns its keep a second time, catching what the cheaper models miss, the way it did on the security scan.</li></ol><p>You get the deep strategy and a frontier second set of eyes, and you keep the expensive model off the high-volume work that drives most of the cost. Frontier thinking, cheaper hands, frontier review. It is the closest thing to an auto-router until the real one shows up.</p><h3 id="pro-tip-2-match-the-effort-setting-to-the-task" tabindex="-1">Pro tip #2: match the effort setting to the task <a class="header-anchor" href="#pro-tip-2-match-the-effort-setting-to-the-task" aria-label="Permalink to &quot;Pro tip #2: match the effort setting to the task&quot;">​</a></h3><p>Fable 5 has effort settings, and they matter more than you would expect. Effort controls how hard it thinks before it answers, which means it also controls your bill.</p><ol><li>High is the sweet spot for most work. Start here.</li><li>Extra high for the hardest, long-running tasks where you want it to grind.</li><li>Low or medium: for quick, back-and-forth sessions where you do not need the full engine.</li></ol><p>Reaching for extra high on simple work is how you burn tokens for nothing. Dialing down to low or medium on interactive chats keeps the cost sane. It is the closest thing to the auto-router I want, just done by hand. You pick the gear, the model does the rest.</p><h3 id="pro-tip-3-let-it-audit-your-own-setup" tabindex="-1">Pro tip #3: let it audit your own setup <a class="header-anchor" href="#pro-tip-3-let-it-audit-your-own-setup" aria-label="Permalink to &quot;Pro tip #3: let it audit your own setup&quot;">​</a></h3><p>One more move that paid off: point Fable 5 at your own setup. Have it review your most important skills, your CLAUDE.md files, and your configs to make sure they still make sense.</p><p>Most of that scaffolding was written for weaker models. It is full of hand-holding steps, workarounds, and assumptions a smarter model does not need and can be held back by. This is a major jump in intelligence, and you do not want to cap it with outdated instructions or stale data. Let the smarter model clean up the rules it has to follow, then get out of its way.</p><h3 id="pulling-back" tabindex="-1">Pulling back <a class="header-anchor" href="#pulling-back" aria-label="Permalink to &quot;Pulling back&quot;">​</a></h3><p>Let me be honest about where I am coming from. I use every tool out there. Claude is my daily driver, but I am constantly in Codex and Cursor too, and they each have real strengths. I am not a one-model person.</p><p>But the moment I got access to Claude Fable 5, I could not put it down. I disappeared into it all weekend. I could feel the level of intelligence I had in my hands and how far ahead of the current options it was, and I used it to do as much work as I possibly could: running many agents at once, remote controlling it from my phone when I was away from the desk, completely hooked.</p><p>I do not know how long this window stays open. Others will catch up. But until they do, this model is a real competitive advantage sitting on the table, and I would approach that as deliberately as you can. Because it really is that good.</p><h3 id="the-verdict" tabindex="-1">The verdict <a class="header-anchor" href="#the-verdict" aria-label="Permalink to &quot;The verdict&quot;">​</a></h3><p>Claude Fable 5 is an excellent model. It is the first one in a while that genuinely feels like more intelligence than what came before, and that gap is the whole game right now. We are at the point where access to more intelligence than the person next to you is the advantage. This is the first model that makes that real. I did engineer-level work without being an engineer. Even priced entirely at frontier rates, the workload still cleared a profit, and run with any care about routing, the return is enormous.</p><p>So here is my recommendation. If you can afford it, use it, and use it now, especially on the work where a real quality jump changes the outcome. The first month at full capacity is where the advantage lives, so move fast. Be deliberate about what you run on it until the routing catches up, because the bill is driven by volume, not by the few hard prompts that justify the model.</p><p>What an incredible model! 💙</p><hr><h2 id="研究摘要" tabindex="-1">研究摘要 <a class="header-anchor" href="#研究摘要" aria-label="Permalink to &quot;研究摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：非工程師花 $1,442（10 億 token）全面實測 Fable 5，認為在 UI 建站、寫作一致性、安全審計、主動預判四維度皆為質的躍進，提出 Think→Build→Review 混合模型路由策略降本。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ol><li><strong>Eye test &gt; benchmarks</strong>：以實際產出（非跑分）評估模型；Fable 5 是繼 Opus 4.5 後第一次「big model feel」</li><li><strong>UI/UX 一鏡到底</strong>：幾乎 one-shot 重建整個 Webflow 網站 + 80 頁新站 + programmatic clip factory（HeyGen/HyperFrames/ElevenLabs pipeline）</li><li><strong>安全發現</strong>：在 GPT 5.5 和 Claude 4.8 都未標記的 repo 中首次掃描即發現嚴重漏洞並現場修補</li><li><strong>成本策略</strong>：Think (Fable 5) → Build (4.8/Sonnet) → Review (Fable 5) 三段式路由 + effort 調檔可大幅控制開銷</li><li><strong>人性化預判</strong>：主動告知 cron job 剩餘時間，展現「anticipate vs respond」區別</li></ol><h3 id="關鍵數據-工具" tabindex="-1">關鍵數據 / 工具 <a class="header-anchor" href="#關鍵數據-工具" aria-label="Permalink to &quot;關鍵數據 / 工具&quot;">​</a></h3><ul><li>1.04B tokens / $1,442 成本</li><li>產出價值估 $30K–$50K（前代理公司報價）</li><li>模型比較：GPT 5.5、Claude 4.8、Claude Sonnet 4.6</li><li>工具鏈：Figma → Claude Design → Webflow → HeyGen / HyperFrames / ElevenLabs / Cloudflare Workers</li><li>Effort 分檔建議：high（甜蜜點）/ extra high（磨題）/ low-medium（對話）</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ol><li><strong>偏向正面</strong>：作者為 AI consulting firm (Tenex) 創辦人，有動機偏好 Claude 生態——但提供了具體成本數字與失敗對照（4.8/GPT 5.5 的失敗記錄），增強可信度</li><li><strong>自動路由缺口</strong>：作者最強烈的訴求（auto-router）恰好對應 workspace 的 multi-mode/effort 策略——可驗證我們的 pilot 分檔是否實現了他描述的手動路由</li><li><strong>Pro tip #3 直接適用</strong>：「讓更強模型審計為弱模型寫的規則」= 我們的 <code>/autoload-evolution</code> 場景，但需注意模型世代切換時 rules 重評（core.md §Framework Integrity 已涵蓋）</li></ol><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>說明</th></tr></thead><tbody><tr><td>A. Workspace 可行動性 (30%)</td><td>8/10</td><td>Think→Build→Review 路由策略與 effort 分檔直接對應 pilot 體系；audit your setup 呼應 autoload-evolution</td></tr><tr><td>B. 創新性 (20%)</td><td>6/10</td><td>混合路由非新概念，但「非工程師 eye test」視角與量化成本分析提供差異化價值</td></tr><tr><td>C. 證據品質 (20%)</td><td>8/10</td><td>具體 token 數、美元成本、多模型失敗對照；但缺少可重現的 benchmark 或 repo 連結</td></tr><tr><td>D. 技術深度 (15%)</td><td>5/10</td><td>使用者視角為主，未涉及 prompt 工程、API 參數、架構細節</td></tr><tr><td>E. 泛化性 (15%)</td><td>7/10</td><td>建站/寫作/安全/agentic pipeline 覆蓋廣泛，但具體場景偏向 marketing agency</td></tr><tr><td><strong>加權總分</strong></td><td><strong>6.95/10</strong></td><td>8×0.3+6×0.2+8×0.2+5×0.15+7×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule <strong>理由</strong>：Think→Build→Review 路由框架驗證了 pilot 分檔策略，effort 分檔建議可交叉參考 core.md 的 effort 先於 model 原則</p>',82)])])}const p=t(n,[["render",r]]);export{g as __pageData,p as default};
